"""Local socket so `pa show` can raise the running dashboard.

Protocol is one line per connection: ``show`` or ``show <tab index>``.
"""

from __future__ import annotations

import ast
import getpass
import json
import logging
import os
import socket
import subprocess
import tempfile
import threading
from collections.abc import Callable
from pathlib import Path

from personal_assistant_dashboard.utils import run_cmd

logger = logging.getLogger(__name__)

SOCKET_PATH = (
    Path(os.environ["XDG_RUNTIME_DIR"]) / "pa-dashboard.sock"
    if os.environ.get("XDG_RUNTIME_DIR")
    else Path(tempfile.gettempdir()) / f"pa-dashboard-{getpass.getuser()}.sock"
)


def parse_request(line: str) -> int | None:
    """Return the tab index from a request line, None for a bare ``show``.

    Raises ValueError on anything else.
    """
    parts = line.split()
    if not parts or parts[0] != "show" or len(parts) > 2:
        raise ValueError(f"bad request: {line!r}")
    return int(parts[1]) if len(parts) == 2 else None


def serve(
    on_show: Callable[[int | None], None], path: Path = SOCKET_PATH
) -> socket.socket | None:
    """Listen on *path*; call *on_show* from a daemon thread per request.

    *on_show* runs off the Tk thread — pass something that schedules.
    Returns None where AF_UNIX is unavailable.
    """
    if not hasattr(socket, "AF_UNIX"):
        logger.info("IPC: AF_UNIX unavailable, `pa show` disabled")
        return None
    # ponytail: unconditional unlink — a second `pa gui` takes the socket
    # from the first. Probe with connect() first if two instances ever matter.
    path.unlink(missing_ok=True)
    server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    server.bind(str(path))
    server.listen()

    def _loop() -> None:
        while True:
            try:
                conn, _ = server.accept()
            except OSError:
                return  # closed by close()
            with conn:
                try:
                    request = conn.recv(256).decode()
                    try:
                        on_show(parse_request(request))
                        reply = b"ok\n"
                    except ValueError as exc:
                        reply = f"error: {exc}\n".encode()
                    conn.sendall(reply)
                except (OSError, UnicodeDecodeError) as exc:
                    # Client left early or sent garbage; keep listening.
                    logger.debug("IPC: request failed: %s", exc)

    threading.Thread(target=_loop, daemon=True, name="ipc").start()
    return server


def close(server: socket.socket | None, path: Path = SOCKET_PATH) -> None:
    if server is None:
        return
    server.close()
    path.unlink(missing_ok=True)


def send_show(tab: int | None, path: Path = SOCKET_PATH) -> str:
    """Send a show request; return the dashboard's reply.

    Raises OSError when no dashboard is listening.
    """
    if not hasattr(socket, "AF_UNIX"):
        raise OSError("AF_UNIX unavailable on this platform")
    with socket.socket(socket.AF_UNIX, socket.SOCK_STREAM) as client:
        client.settimeout(5)
        client.connect(str(path))
        client.sendall(b"show" if tab is None else f"show {tab}".encode())
        return client.recv(256).decode().strip()


_WINDOW_CALLS = [
    "gdbus",
    "call",
    "--session",
    "--dest",
    "org.gnome.Shell",
    "--object-path",
    "/org/gnome/Shell/Extensions/Windows",
    "--method",
]
_WINDOW_CALLS_IFACE = "org.gnome.Shell.Extensions.Windows"


def activate_window(title: str) -> bool:
    """Raise and focus our window via the window-calls GNOME Shell extension.

    Mutter treats Tk's lift()/focus_force() from a process the user is not
    interacting with as focus stealing and shows an "is ready" notification
    instead. GNOME Shell activating the window itself is not subject to that.
    Same extension claude-dashboard uses. False when gdbus, the extension, or
    the window is missing — the caller falls back to lift().
    """
    try:
        listed = run_cmd([*_WINDOW_CALLS, f"{_WINDOW_CALLS_IFACE}.List"], timeout=3)
        if listed.returncode != 0:
            logger.debug("window-calls List failed: %s", listed.stderr.strip())
            return False
        # gdbus prints a GVariant tuple; literal_eval handles both its quote
        # styles, which a regex strip of the wrapper gets wrong.
        (payload,) = ast.literal_eval(listed.stdout.strip())
        windows = json.loads(payload)
        ids = [w["id"] for w in windows if w.get("title") == title]
        if not ids:
            logger.debug("window-calls: no window titled %r", title)
            return False
        activated = run_cmd(
            [*_WINDOW_CALLS, f"{_WINDOW_CALLS_IFACE}.Activate", str(ids[0])],
            timeout=3,
        )
    except (
        OSError,
        subprocess.TimeoutExpired,
        SyntaxError,
        TypeError,
        ValueError,
    ) as exc:
        logger.debug("window-calls unavailable: %s", exc)
        return False
    return activated.returncode == 0
